local function addr(p) return tonumber(ffi.cast("uintptr_t",p)) end
local function ptr(p) return ffi.cast("void *",p) end
local function u64(p) return tonumber(memory.unpack("u64",memory.read(p,8))) end
local function substitute(b,marker,value)
 local pattern=string.rep(string.char(marker),8)
 local a,e=b:find(pattern,1,true)
 if not a or b:find(pattern,e+1,true) then return nil end
 return b:sub(1,a-1)..memory.pack("u64",value)..b:sub(e+1)
end
local card_strings, card_crests
local transfer_market = (function()
-- Read-only data binding for the FL 2027 Master League transfer tile.
local m = {}

local CAREER_ROOT = 0x3705E10
local CAREER_DATE = 0x1642A24
local CAREER_CURRENCY = 0x17893F8
local MARKET_ROOT = 0x36FCCC8
local ROW_SIZE = 0x30
local MAX_ROWS = 512
local MAX_ADDRESS = 0x00007FFFFFFFFFFF
local MONTH_LENGTHS = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31}
-- FL 2027 uses fixed rates per raw fee unit and a common upper bound.
local CURRENCIES = {
    [0] = {"¥", 12500}, {"€", 100}, {"$", 110}, {"£", 90}, {"R$", 430},
}

local function u32(data, offset)
    local a, b, c, d = data:byte(offset, offset + 3)
    return a + b * 256 + c * 65536 + d * 16777216
end

local function pointer(data, offset)
    local value = u32(data, offset) + u32(data, offset + 4) * 4294967296
    if value == 0 or (value >= 0x10000 and value <= MAX_ADDRESS) then return value end
end

local function date_key(year, month, day)
    local days = MONTH_LENGTHS[month]
    if month == 2 and year % 4 == 0 and (year % 100 ~= 0 or year % 400 == 0) then days = 29 end
    if not days or year < 1 or year > 9999 or day < 1 or day > days then return end
    return year * 10000 + month * 100 + day
end

local function read_date(data, offset)
    local lo, hi, month, day = data:byte(offset, offset + 3)
    return date_key(lo + hi * 256, month, day)
end

function m.supports(read, base)
    return read(base + 0xB19750, 8) == "\x40\x57\x48\x83\xEC\x30\x48\x8B"
       and read(base + 0x14B6A60, 8) == "\x48\x8B\x05\xA9\xF3\x24\x02\xC3"
       and read(base + 0x15765EE, 10) == "\x48\x8B\x50\x48\x8B\x82\x24\x2A\x64\x01"
       and read(base + 0x4AF2135, 7) == "\x44\x8B\x81\xF8\x93\x78\x01"
end

function m.display_fee(raw, currency_id)
    if raw == 0 then return "Free transfer" end
    local currency = CURRENCIES[currency_id]
    if not currency then return "" end
    local amount = math.min(raw * currency[2], 999999900000)
    local digits = string.format("%.0f", amount):reverse():gsub("(%d%d%d)", "%1,"):reverse():gsub("^,", "")
    return currency[1] .. digits
end

-- Call supports once with the build's image base. read must return nil on unreadable pages.
function m.snapshot(read, base)
    local function bytes(address, length)
        if not address or address < 0x10000 or address > MAX_ADDRESS - length then return end
        local data = read(address, length)
        if type(data) == "string" and #data == length then return data end
    end

    local function at(address)
        local data = bytes(address, 8)
        if data then return pointer(data, 1) end
    end

    local function sample()
        local career_root = at(base + CAREER_ROOT)
        local career = career_root and at(career_root + 0x48)
        local clock = career and bytes(career + CAREER_DATE, 4)
        local today = clock and read_date(clock, 1)
        if not today then return end
        local currency = bytes(career + CAREER_CURRENCY, 4)

        local owner = at(base + MARKET_ROOT)
        local handle = owner and at(owner + 0x78)
        local source = handle and at(handle + 8)
        local containers = source and bytes(source + 0x100, 16)
        if not containers then return end
        local container = pointer(containers, 1)
        if container == 0 then container = pointer(containers, 9) end
        if container == 0 then container = source + 0xA0 end
        if not container then return end

        local bounds = bytes(container + 0x48, 16)
        if not bounds then return end
        local first, last = pointer(bounds, 1), pointer(bounds, 9)
        if not first or not last then return end
        local size = last - first
        if size < 0 or size > MAX_ROWS * ROW_SIZE or size % ROW_SIZE ~= 0 then return end
        local data = size == 0 and "" or bytes(first, size)
        if not data or bounds ~= bytes(container + 0x48, 16)
           or containers ~= bytes(source + 0x100, 16)
           or owner ~= at(base + MARKET_ROOT) or handle ~= at(owner + 0x78) or source ~= at(handle + 8)
           or career_root ~= at(base + CAREER_ROOT) or career ~= at(career_root + 0x48)
           or clock ~= bytes(career + CAREER_DATE, 4) then return end

        local rows = {}
        for offset = 1, size, ROW_SIZE do
            local date = read_date(data, offset + 0x18)
            local player_id = u32(data, offset + 0x08)
            if date and date <= today and player_id ~= 0 then
                local fee = u32(data, offset + 0x14)
                rows[#rows + 1] = {
                    date = date,
                    player_id = player_id,
                    player_slot = u32(data, offset + 0x04) % 65536,
                    to_identity = u32(data, offset + 0x0C),
                    to_team = math.floor(u32(data, offset + 0x0C) / 16384),
                    from_identity = u32(data, offset + 0x10),
                    from_team = math.floor(u32(data, offset + 0x10) / 16384),
                    fee = fee >= 2147483648 and fee - 4294967296 or fee,
                    kind = u32(data, offset),
                }
            end
        end
        return {date = today, currency = currency and u32(currency, 1), rows = rows}
    end

    return sample()
end

-- Window boundaries and snapshot dates use YYYYMMDD integers.
function m.window_prices(rows, start_date, end_date)
    assert(start_date <= end_date, "Transfer window ends before it starts")
    local matches = {}
    for _, row in ipairs(rows) do
        if start_date <= row.date and row.date <= end_date then
            matches[#matches + 1] = {row = row, order = #matches + 1}
        end
    end
    table.sort(matches, function(a, b)
        if a.row.fee == b.row.fee then return a.order < b.order end
        return a.row.fee > b.row.fee
    end)
    for index, match in ipairs(matches) do matches[index] = match.row end
    return matches
end

return m

end)()
-- Read FL 2027's career data into fixed-length strings for the dashboard movie.
local function u32_at(address)
    local bytes = memory.read(address, 4)
    if type(bytes) == "string" and #bytes == 4 then
        return tonumber(memory.unpack("u32", bytes))
    end
end

local function compact_name(address, length)
    local bytes = memory.read(address, length)
    if type(bytes) ~= "string" then return end
    local name = bytes:match("^[^%z]*")
    if name ~= "" and not name:find("[%c]") then return name end
end

local function write_card_text(destination, value)
    local length = math.min(#value, 47)
    -- Each native text field has a 48-byte slot.
    while length > 0 do
        local following = value:byte(length + 1)
        if not following or following < 128 or following >= 192 then break end
        length = length - 1
    end
    memory.write(destination, value:sub(1, length) .. "\0")
end

local function set_card(index, value)
    write_card_text(card_strings + index * 48, value)
end

local function club_record(career, identity)
    if not identity then return end
    local team_id = math.floor(identity / 16384)
    local slot = identity % 16384
    if team_id == 0 or team_id >= 0x3fff0 or slot > 750 then return end
    local address = career + 0xadf4bc + slot * 0x690
    if u32_at(address) == identity then return address end
end

local function first_favourite(career)
    -- MLCoachHallPlayer takes bit 1 and sorts by newest packed date first.
    local best_date, best_id, best_name
    for slot = 0, 79 do
        local entry = career + 0x1719b84 + slot * 0x15fc
        local flags = u32_at(entry + 0x10)
        if flags and math.floor(flags / 2) % 2 == 1 then
            local key, id, packed = u32_at(entry), u32_at(entry + 4), u32_at(entry + 0x14)
            local date = packed and (packed % 65536 * 65536
                + math.floor(packed / 65536) % 256 * 256 + math.floor(packed / 16777216))
            if key and id and id > 0 and date and (not best_date or date > best_date) then
                local index = key % 65536
                local player = career + index * 0x17c
                if index <= 30000 and u32_at(player + 0x30) == id then
                    best_date, best_id = date, id
                    best_name = compact_name(player + 0x38, 0x75 - 0x38)
                end
            end
        end
    end
    return best_id, best_name
end

local function update_favourite(career)
    local id, name = first_favourite(career)
    set_card(11, name or (id and ("Player " .. id) or "List is empty"))
end

local month_names = {"Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"}
local month_days = {31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31}

local function next_day(year, month, day)
    local leap = year % 4 == 0 and (year % 100 ~= 0 or year % 400 == 0)
    local days = month == 2 and leap and 29 or month_days[month]
    if day < days then return year, month, day + 1 end
    if month < 12 then return year, month + 1, 1 end
    return year + 1, 1, 1
end

local function packed_day(year, month, day)
    return year + month * 65536 + day * 16777216
end

local function grouped_number(value)
    return string.format("%.0f", value):reverse():gsub("(%d%d%d)", "%1,"):reverse():gsub("^,", "")
end

local function transfer_window(date)
    local year, month = math.floor(date / 10000), math.floor(date / 100) % 100
    if month >= 7 then return year * 10000 + 701, year * 10000 + 831 end
    return year * 10000 + 101, year * 10000 + 131
end

local function transfer_card(career, data, best, start)
    local start_date, end_date = transfer_window(data.date)
    if start_date ~= start or best and best.date > data.date then
        best = nil
    end
    for _, transfer in ipairs(transfer_market.window_prices(data.rows, start_date, end_date)) do
        if transfer.fee >= 0 then
            if not best or transfer.fee > best.fee then best = transfer end
            break
        end
    end
    if not best then return nil, start_date, "No transfers", "", "", 0, 0 end

    local address = career + best.player_slot * 0x17c
    local player_name
    if best.player_slot <= 30000 and u32_at(address + 0x30) == best.player_id then
        player_name = compact_name(address + 0x38, 0x75 - 0x38)
    end
    local from_record = club_record(career, best.from_identity)
    local to_record = club_record(career, best.to_identity)
    local to_club = to_record and (compact_name(to_record + 0x44, 8) or compact_name(to_record + 4, 64))
    return best, start_date, player_name or "Player " .. best.player_id,
        to_club or "Club " .. best.to_team, transfer_market.display_fee(best.fee, data.currency),
        from_record and best.from_identity or 0, to_record and best.to_identity or 0
end

local function training_summary(career, managed)
    if not managed then return "" end
    local club_slot = managed % 16384
    local total = 0
    -- The native training lookup walks 82 records of 0x170 bytes. Validate
    -- each identity against the career player table and count our club only.
    for index = 0, 81 do
        local address = career + 0x16bf710 + index * 0x170
        local slot = u32_at(address)
        local player_id = u32_at(address + 4)
        if slot and player_id and player_id > 0 and slot % 65536 <= 30000 then
            local player = career + (slot % 65536) * 0x17c
            local ownership = u32_at(player + 0x12c)
            if ownership and ownership % 65536 == club_slot and u32_at(player + 0x30) == player_id then
                total = total + 1
            end
        end
    end
    if total == 0 then return "No assignments" end
    return total == 1 and "1 assignment" or string.format("%d assignments", total)
end

local current_career, current_clock, next_market_poll, window_best, window_start
local function card_data_tick()
    local owner = u64(base + 0x3705e10)
    if owner == 0 then return end
    local career = u64(owner + 0x48)
    if career == 0 then return end
    local clock = u32_at(career + 0x1642a24)
    if not clock then return end
    local year, month, day = clock % 65536, math.floor(clock / 65536) % 256, math.floor(clock / 16777216)
    if year < 2000 or year > 9999 or not month_days[month] or day < 1 or day > 31 then return end

    if current_career ~= career or current_clock ~= clock then
        if current_career ~= career or current_clock and current_clock % 65536 > year then
            window_best, window_start = nil, nil
            for index = 5, 11 do set_card(index, "") end
            memory.write(card_crests + 6 * 4, string.rep("\0", 8))
        end
        current_career, current_clock, next_market_poll = career, clock, frame
        local dates, crests = {}, {}
        for index = 1, 5 do
            local key = packed_day(year, month, day)
            dates[key] = index
            set_card(index - 1, string.format("%02d %s", day, month_names[month]))
            year, month, day = next_day(year, month, day)
        end
        local managed = u32_at(career + 0x1798ab0)
        -- The executable's fixture lookup bounds this flat table at 0x32C8 records.
        -- Read each year once per career day. Menu rendering only reads our strings.
        local size = 0x32c8 * 0x254
        local table_data = memory.read(career + 0xe9ff08, size)
        if managed and type(table_data) == "string" and #table_data == size then
            for offset = 1, size, 0x254 do
                local a, b, c, d = table_data:byte(offset + 8, offset + 11)
                local index = dates[a + b * 256 + c * 65536 + d * 16777216]
                if index then
                    local home = tonumber(memory.unpack("u32", table_data:sub(offset + 20, offset + 23)))
                    local away = tonumber(memory.unpack("u32", table_data:sub(offset + 24, offset + 27)))
                    if home == managed or away == managed then
                        local rival = home == managed and away or home
                        if club_record(career, rival) then crests[index] = rival end
                    end
                end
            end
        end
        for index = 1, 5 do
            memory.write(card_crests + (index - 1) * 4, memory.pack("u32", crests[index] or 0))
        end
        local crest = club_record(career, managed) and managed or 0
        memory.write(card_crests + 5 * 4, memory.pack("u32", crest))
    end

    if frame < next_market_poll then return end
    next_market_poll = frame + 120
    local managed = u32_at(career + 0x1798ab0)
    update_favourite(career)
    set_card(8, training_summary(career, managed))
    local followers = u32_at(career + 0x1798b8c)
    if followers then set_card(10, grouped_number(followers)) end
    local unread = u32_at(control + 0x3e0)
    if unread and unread > 0 then
        set_card(9, unread == 2 and "Unread" or "All read")
    end
    local data = transfer_market.snapshot(memory.read, base)
    if not data then return end
    local player, club, fee, from_crest, to_crest
    window_best, window_start, player, club, fee, from_crest, to_crest =
        transfer_card(career, data, window_best, window_start)
    set_card(5, player)
    set_card(6, club)
    set_card(7, fee)
    memory.write(card_crests + 6 * 4, memory.pack("u32", from_crest) .. memory.pack("u32", to_crest))
end

