function m.data_ready(ctx,filename,data,size,total,offset)
 if career_mode=="bal" and is_asset(filename) then
  bal_visual_ready(data,tonumber(size),tonumber(total),tonumber(offset))
  return
 end
 if not ml_session then return end
 if type(filename)~="string" or filename:lower():gsub("/","\\")~="common\\menu\\general\\modemainmenufl.bin" then return end
 if installed then memory.write(control+8,memory.pack("u32",0)) end
 size=tonumber(size);total=tonumber(total);offset=tonumber(offset)
 if visual and size==visual_size and size==total and offset==0 then
  if not installed or memory.read(data,size)~=visual then log("MLLAYOUT VISUAL SKIPPED unverified data/UI");return end
  memory.write(control+8,memory.pack("u32",1))
  log("MLLAYOUT VISUAL APPLIED v0.80: v39 component structure; native focus; news layers")
  return
 end
 log("MLLAYOUT v0.29 SKIPPED: expected the bundled verified visual asset")
end
function m.resource_tick(ctx)
 frame=frame+1
 if career_mode=="bal" then bal_resource_tick() end
 if installed and control then
  local match=tonumber(ctx.match_id) or 0
  local stadium=tonumber(ctx.stadium) or 65535
  if match<1 or match>=13000 or match~=math.floor(match) then match=0 end
  if stadium<0 or stadium>65535 or stadium~=math.floor(stadium) then stadium=65535 end
  memory.write(control+800,memory.pack("u32",match))
  memory.write(control+804,memory.pack("u32",stadium))
  memory.write(control+792,memory.pack("u32",tonumber(ctx.tournament_id)==103 and 1 or 0))
  if ml_session and frame%1200==0 then log("MLLAYOUT FIXTURE v0.80 match="..match.." stadium="..stadium.." stage="..tonumber(memory.unpack("u32",memory.read(control+812,4)))) end
 end
 if installed and stats_state then
  return_armed=tonumber(memory.unpack("u32",memory.read(stats_state+64,4)))==1
 end
 if ml_session and installed and frame%120==0
    and memory.read(control+8,4)==memory.pack("u32",1) then card_data_tick() end
 if not attempted and frame>=120 then install() end
 if not installed or frame%240~=0 then return end
 if stats_state and (frame%1200==0 or not reported) then
  log(string.format("MLLAYOUT TABLES v0.80 stage=%d status=%d competition=%d source_rows=%d painted=%d header=%d",tonumber(memory.unpack("u32",memory.read(stats_state+88,4))),tonumber(memory.unpack("u32",memory.read(stats_state+4,4))),tonumber(memory.unpack("u32",memory.read(stats_state+16,4))),tonumber(memory.unpack("u32",memory.read(stats_state+20,4))),tonumber(memory.unpack("u32",memory.read(stats_state+24,4))),tonumber(memory.unpack("u32",memory.read(stats_state+72,4)))))
 end
 if frame%1200==0 or not reported then
  log("MLLAYOUT ACTIONS choice="..tostring(u32_at(control+0x3d4))
      .." confirmed="..tostring(u32_at(control+0x3d8))
      .." dispatched="..tostring(u32_at(control+0x3dc)))
  log("MLLAYOUT CARDS updates="..tostring(u32_at(control+0x3e4))
      .." calendar="..tostring(compact_name(card_strings,48))
      .." transfer="..tostring(compact_name(card_strings+240,48))
      .." favourite="..tostring(compact_name(card_strings+528,48))
      .." notifications="..tostring(u32_at(control+0x3e0)))
  log(string.format("MLLAYOUT STYLE v0.80 groups=%d menuChoices=%d tableChoices=%d focusGroup=%d focusItem=%d",tonumber(memory.unpack("u32",memory.read(control+768,4))),tonumber(memory.unpack("u32",memory.read(control+772,4))),tonumber(memory.unpack("u32",memory.read(control+776,4))),tonumber(memory.unpack("u32",memory.read(control+780,4))),tonumber(memory.unpack("u32",memory.read(control+784,4)))))
 end
 local ticks=tonumber(memory.unpack("u32",memory.read(control,4)))
 local hidden=tonumber(memory.unpack("u32",memory.read(control+4,4)))
 local resets=tonumber(memory.unpack("u32",memory.read(control+12,4)))
 if hidden>0 and not reported then
 local stage=tonumber(memory.unpack("u32",memory.read(control+20,4)))
 local names=tonumber(memory.unpack("u32",memory.read(control+24,4)))
 log("MLLAYOUT ALIGN calls="..tonumber(memory.unpack("u32",memory.read(control+36,4))))
 log(string.format("MLLAYOUT HEADER stage=%d text_updates=%d club=%s coach=%s fixture=%s",stage,names,memory.read(control+64,128):match("^[^%z]*"),memory.read(control+192,128):match("^[^%z]*"),memory.read(control+320,128):match("^[^%z]*"))) log(string.format("MLLAYOUT FIXTURE KEYS home=%x away=%x",tonumber(memory.unpack("u32",memory.read(control+704,4))),tonumber(memory.unpack("u32",memory.read(control+708,4))))) log(string.format("MLLAYOUT UI STATUS ticks=%d flag_calls=%d focus_resets=%d",ticks,hidden,resets));reported=true end
end
